			'<path d="' + veins + '" stroke="#b5dc8e" stroke-opacity=".22" stroke-width="1.3" fill="none"/>' +
			'<circle cx="' + Math.round(x) + '" cy="' + Math.round(y) + '" r="' + r1(r * 0.05) + '" fill="#a9cf86" opacity=".35"/>|' +
			'<use href="#' + id + '" x="' + so + '" y="' + Math.round(so * 1.3) + '"/>';
