		return rel('M' + P(0, 0) + 'C' + P(len * 0.3, w * 0.75) + ' ' + P(len * 0.75, w * 0.85) + ' ' + P(len, 0) +
			'C' + P(len * 0.75, -w * 0.85) + ' ' + P(len * 0.3, -w * 0.75) + ' ' + P(0, 0) + 'Z');
